import { face } from "./data";
export function sellPickerTile(id: string, name: string, variant = ""): string {
  return `<li data-subject="${id}"><div class="pick">${face(id, name, variant)}<button type="button" class="pick-hit" aria-label="Pick ${name}" aria-pressed="false" onclick="this.setAttribute('aria-pressed', this.getAttribute('aria-pressed')==='true'?'false':'true')"></button></div></li>`;
}
export function batchSellRow(id: string, name: string, variant = ""): string {
  return `<li class="bsell-row"><div class="bsell-head"><div class="bsell-thumb" aria-hidden="true">${face(id, name, variant)}</div><div class="bsell-id"><b class="bsell-name ui-line">${name}</b><span class="bsell-meta">Rare · 2 copies</span><button class="bsell-copy" data-testid="bsell-copy" onclick="document.body.dataset.copyClicks=String(Number(document.body.dataset.copyClicks)+1)">Choose copy of ${name}</button></div><button class="bsell-x" aria-label="Remove ${name}" onclick="this.closest('li').remove()">×</button></div><div class="bsell-prices"><label>Starting price<input aria-label="Starting price for ${name}" value="12.00" inputmode="decimal"></label><button class="suggested" onclick="this.previousElementSibling.querySelector('input').value='18.00'">Suggested price for ${name}</button></div></li>`;
}
// Mirrors controlled-input tracking: direct instance assignments do not count as edits.
export const controlledPriceScript = `<script>
window.priceModel={};document.body.dataset.priceChanges='0';
for(const input of document.querySelectorAll('.bsell-prices input,[data-testid="sell-start"]')){
const descriptor=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');let tracked=input.value;
window.priceModel[input.getAttribute('aria-label')]=tracked;
Object.defineProperty(input,'value',{configurable:true,get(){return descriptor.get.call(this)},set(value){tracked=String(value);descriptor.set.call(this,value)}});
input.addEventListener('input',()=>{if(input.value!==tracked){tracked=input.value;window.priceModel[input.getAttribute('aria-label')]=tracked;document.body.dataset.priceChanges=String(Number(document.body.dataset.priceChanges)+1)}});
}
</script>`;

export function singleSellFixture(id = "42"): string {
  return `<!doctype html><html><head><style>body{background:#100b20;color:#ece7f3;font:14px/1.5 system-ui;padding:24px}.deal{display:flex;gap:28px;flex-wrap:wrap}.deal-visual{width:220px}.kc-article{border:2px solid #b3b7c8;border-radius:8px;padding:8px;background:#29374b}.kc-img{width:100%;height:190px;object-fit:cover}.sell-form{width:350px;max-width:100%}.sell-form>button[type=submit]{display:block;width:100%}.fld-big{display:flex;flex-direction:column;gap:6px}input{background:#171127;color:#eee;border:1px solid #9a7c58;border-radius:7px;padding:8px}button{padding:8px;background:#463052;color:#ffe5b3;border:1px solid #b99b60;border-radius:7px}</style></head><body><main class="deal"><div class="deal-visual">${face(id)}</div><div class="deal-info"><form class="sell-form" onsubmit="event.preventDefault();document.body.dataset.submitted='true'"><h1>Sell card</h1><label class="fld fld-big">Starting price<span class="coin-input"><input data-testid="sell-start" inputmode="decimal" aria-label="Starting price" value="12.00"> Kosmo</span></label><label>Reserve price<input data-testid="t3-sell-reserve" aria-label="Reserve price" value="20"></label><button type="submit">Put card on sale</button></form></div></main>${controlledPriceScript}</body></html>`;
}
export function sellManyFixture(batch = false): string {
  const grid = `<ul class="card-grid cp-grid mk-sell-grid" data-testid="sell-sheet-grid">${sellPickerTile("42", "Northern Lights", "kc-veil")}${sellPickerTile("46", "Andromeda", "kc-fa")}</ul>`;
  return `<!doctype html><html><head><meta charset="utf-8"><title>Sell Many fixture</title><style>
body{background:#100b20;color:#ece7f3;font:14px/1.5 system-ui;padding:30px}h1,h2{color:#f3dfb4}.mk-sell-sheet{background:#231830;color:#ece7f3;border:1px solid #8c7043;border-radius:14px;width:1000px;max-width:90vw;padding:24px}dialog::backdrop{background:#100b20cc}.card-grid{display:grid;grid-template-columns:repeat(3,180px);gap:20px;list-style:none;padding:0}.pick{position:relative}.kc-article{margin:0}.kc{background:#29374b;border:2px solid #b3b7c8;border-radius:8px;overflow:hidden}.kc-img{display:block;width:100%;height:180px;object-fit:cover}.kc-name{font:16px Georgia;margin:8px}.kc footer{font-size:10px;padding:8px}.pick-hit{position:absolute;inset:0;border:2px solid transparent;background:transparent;border-radius:8px;cursor:pointer}.pick-hit[aria-pressed=true]{border-color:#ffdb87;box-shadow:0 0 0 3px #ffdb8780}button{background:#403051;color:#ffe5b3;border:1px solid #b99b60;border-radius:7px;padding:8px}button:focus-visible{outline:2px solid #ffdb87;outline-offset:3px}.bsell-list{max-width:740px;padding:0;list-style:none}.bsell-row{border:1px solid #655039;background:#231830;border-radius:12px;padding:18px;margin-bottom:16px}.bsell-head{display:flex;gap:16px;align-items:center}.bsell-thumb{width:72px;flex:none}.bsell-thumb .kc-img{height:75px}.bsell-thumb .kc-name{font-size:8px;margin:3px}.bsell-thumb .kc footer{font-size:7px;padding:3px}.bsell-id{display:flex;flex-direction:column;align-items:flex-start;gap:8px;flex:1}.bsell-name{font-size:18px;color:#ffe5b3}.bsell-prices{display:flex;gap:16px;align-items:center;margin-top:16px}input{margin-left:10px;background:#171127;color:#eee;padding:7px;border:1px solid #655039;border-radius:7px}
</style></head><body data-copy-clicks="0"><h1>Sell Many</h1>${batch ? `<main class="screen bsell"><ul class="bsell-list">${batchSellRow("42", "Northern Lights", "kc-veil")}${batchSellRow("46", "Andromeda", "kc-fa")}</ul><button data-testid="submit-sales" onclick="document.body.dataset.submitted='true'">Put cards on sale</button></main>${controlledPriceScript}` : `<dialog class="mk-sell-sheet" aria-label="What do you want to sell?"><h2>Sell Many</h2><div class="mk-sell">${grid}</div><button data-testid="sell-many-go" onclick="document.body.dataset.continued='true'">Continue</button></dialog><script>document.querySelector('dialog').showModal()</script>`}</body></html>`;
}
